    await choose(root);
    await expect(control.getEntryChanges()).toEqual([]);
    await expect(control.getState().acceptanceCut).toBeUndefined();
    await setCut(root, MAIN, 26);
    await expect(control.getEntryChanges().filter(change => change.from === ALT && change.to === DA && change.toStage === QUALIFYING)).toHaveLength(3);
    await setCut(root, QUALIFYING, 8);
    await expect(control.getEntryChanges().filter(change => change.from === ALT && change.to === ALT && change.toStage === QUALIFYING)).toHaveLength(3);
