    const scores = [...canvasElement.querySelectorAll('.chc-game-score')];
    await expect(scores.map(score => score.textContent)).toEqual(['7', '3', '6', '5', '6', '6']);
    await expect(getComputedStyle(scores[0]).color).toBe('rgb(221, 243, 74)');
