  const fixture = seededDraw({
    drawSize: 32,
    seedsCount: 8
  });
  const {
    series,
    scaleName
  } = buildPressureSeries({
    matchUps: fixture.matchUps
  });
  const wrapper = panel('The same draw, hardest slot first', 'Re-sorted on slotDifficulty. Read this as a shape check, not a ranking: slotDifficulty is dominated by the ' + 'participant’s own rating (Spearman -0.986 against it on a real 99-entrant field), so the order is close ' + 'to the rating order inverted. What it does show honestly is the gradient — how steeply the road gets ' + 'harder as you go down the field.');
  buildPressureHorizon(wrapper, series, {
    scaleName,
    width: 560,
    order: HORIZON_ORDER.DIFFICULTY
  });
